package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonWriter_value_TriageGen0Test {

    private StringWriter stringWriter;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() throws IOException {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @After
    public void tearDown() throws IOException {
        jsonWriter.close();
    }

    @Test
    public void testValue_Null() throws IOException {
        JsonWriter writer = jsonWriter.nullValue();
        assertEquals("null", stringWriter.toString());
    }

    @Test
    public void testValue_IntegerValue() throws IOException {
        JsonWriter writer = jsonWriter.value(123);
        assertEquals("123", stringWriter.toString());
    }

    @Test
    public void testValue_LongValue() throws IOException {
        JsonWriter writer = jsonWriter.value(123L);
        assertEquals("123", stringWriter.toString());
    }

    @Test
    public void testValue_DoubleValue() throws IOException {
        JsonWriter writer = jsonWriter.value(123.45);
        assertEquals("123.45", stringWriter.toString());
    }

    @Test
    public void testValue_NegativeDoubleValue() throws IOException {
        JsonWriter writer = jsonWriter.value(-123.45);
        assertEquals("-123.45", stringWriter.toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_PositiveInfinity() throws IOException {
        jsonWriter.setLenient(false);
        jsonWriter.value(Double.POSITIVE_INFINITY);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_NegativeInfinity() throws IOException {
        jsonWriter.setLenient(false);
        jsonWriter.value(Double.NEGATIVE_INFINITY);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_NaN() throws IOException {
        jsonWriter.setLenient(false);
        jsonWriter.value(Double.NaN);
    }

    @Test
    public void testValue_PositiveInfinity_Lenient() throws IOException {
        jsonWriter.setLenient(true);
        jsonWriter.value(Double.POSITIVE_INFINITY);
        assertEquals("Infinity", stringWriter.toString());
    }

    @Test
    public void testValue_NegativeInfinity_Lenient() throws IOException {
        jsonWriter.setLenient(true);
        jsonWriter.value(Double.NEGATIVE_INFINITY);
        assertEquals("-Infinity", stringWriter.toString());
    }

    @Test
    public void testValue_NaN_Lenient() throws IOException {
        jsonWriter.setLenient(true);
        jsonWriter.value(Double.NaN);
        assertEquals("NaN", stringWriter.toString());
    }
}
